// Original Mont circular gallery: upright art on a gently tilted elliptical wheel.
function wheelAngle(index, turns) {
  return 2 * Math.PI * (turns + index / 10) - Math.PI / 2;
}
function wheelDepth(index, turns) {
  return Math.sin(wheelAngle(index, turns));
}
function wheelScale(index, turns) {
  return 0.77 + 0.23 * wheelDepth(index, turns);
}

function carouselRamp(u) {
  return u * u * u - 0.5 * u * u * u * u;
}
function carouselTravel(ms) {
  // Integrated smoothstep velocity: stop at 3.8s, resume at 7.75s, cruise at 8.65s.
  return ms < 3000 ? ms / 9200
    : ms < 3800 ? (3000 + 800 * ((ms - 3000) / 800 - carouselRamp((ms - 3000) / 800))) / 9200
    : ms < 7750 ? 3400 / 9200
    : ms < 8650 ? (3400 + 900 * carouselRamp((ms - 7750) / 900)) / 9200
    : (3850 + ms - 8650) / 9200;
}
function carouselEase(u) {
  return u * u * u * (10 - 15 * u + 6 * u * u);
}
function carouselFeature(ms) {
  // 200ms settle, 900ms expansion, 1.8s hold, 800ms return, 250ms settle.
  return ms < 4000 ? 0
    : ms < 4900 ? carouselEase((ms - 4000) / 900)
    : ms < 6700 ? 1
    : ms < 7500 ? 1 - carouselEase((ms - 6700) / 800)
    : 0;
}
function wheelFeature(index, feature) {
  return index === 5 ? feature : 0;
}

export default defineSpanScene({
  id: "circle-carousel",
  width: 1920,
  height: 1080,
  durationMs: 14000,
  editPreviewMs: 1250,
  variables: {
    width: numberVar(1920),
    height: numberVar(1080),
    speed: numberVar(1),
    background: colorVar("#F6F5F1"),
    poster01: stringVar("data:image/jpeg;base64,"),
    poster02: stringVar("data:image/jpeg;base64,"),
    poster03: stringVar("data:image/jpeg;base64,"),
    poster04: stringVar("data:image/jpeg;base64,"),
    poster05: stringVar("data:image/jpeg;base64,"),
    poster06: stringVar("data:image/jpeg;base64,"),
    poster07: stringVar("data:image/jpeg;base64,"),
    poster08: stringVar("data:image/jpeg;base64,"),
    poster09: stringVar("data:image/jpeg;base64,"),
    poster10: stringVar("data:image/jpeg;base64,"),
  },
  computeds: {
    scale: computed.number(() => Math.min(vars.width / 1920, vars.height / 1080)),
    cycle: computed.number(() => (time.ms * vars.speed) % 14000),
    turns: computed.number(() => carouselTravel(computed.cycle) - 3400 / 9200),
    feature: computed.number(() => carouselFeature(computed.cycle)),
  },
  render({ vars, computed }) {
    return <Scene width={vars.width} height={vars.height}>
      <Rect id="background" width={vars.width} height={vars.height} fill={vars.background} />
      <Group id="letterbox" x={(vars.width - 1920 * computed.scale) / 2} y={(vars.height - 1080 * computed.scale) / 2} width={0} height={0} pivotX={0} pivotY={0} scaleX={computed.scale} scaleY={computed.scale}>
        <Repeat items={[
          { src: vars.poster01 }, { src: vars.poster02 },
          { src: vars.poster03 }, { src: vars.poster04 },
          { src: vars.poster05 }, { src: vars.poster06 },
          { src: vars.poster07 }, { src: vars.poster08 },
          { src: vars.poster09 }, { src: vars.poster10 },
        ]} render={(poster, index) => (
          <Group
            id={"wheel-poster-" + index}
            x={960 + (660 * Math.cos(wheelAngle(index, computed.turns)) + 38 * wheelDepth(index, computed.turns)) * (1 - wheelFeature(index, computed.feature))}
            y={520 + (260 * wheelDepth(index, computed.turns) - 68 * Math.cos(wheelAngle(index, computed.turns))) * (1 - wheelFeature(index, computed.feature)) + 20 * wheelFeature(index, computed.feature)}
            width={0} height={0} pivotX={0} pivotY={0}
            scaleX={wheelScale(index, computed.turns) * (1 - wheelFeature(index, computed.feature)) + (780 / 368) * wheelFeature(index, computed.feature)}
            scaleY={wheelScale(index, computed.turns) * (1 - wheelFeature(index, computed.feature)) + (780 / 368) * wheelFeature(index, computed.feature)}
            rotation={-5 * Math.cos(wheelAngle(index, computed.turns)) * (1 - wheelFeature(index, computed.feature))}
            rotationX={3 * wheelDepth(index, computed.turns) * (1 - wheelFeature(index, computed.feature))}
            rotationY={-10 * Math.cos(wheelAngle(index, computed.turns)) * (1 - wheelFeature(index, computed.feature))}
            perspective={1400}
            opacity={index === 5 ? 1 : 1 - 0.68 * computed.feature}
            layer={wheelFeature(index, computed.feature) > 0 ? 100 : 10 + 10 * wheelDepth(index, computed.turns)}
          >
            {/* Native depth layers preserve foreground occlusion without swapping image sources. */}
            <Rect id={"wheel-shadow-" + index} x={-138} y={-184} width={276} height={368} fill="#FFFFFF" shadowColor="#262A32" shadowOffsetY={10} shadowBlur={24} shadowOpacity={0.08 + 0.03 * wheelDepth(index, computed.turns)} />
            <Image id={"wheel-art-" + index} src={poster.src} x={-138} y={-184} width={276} height={368} borderWidth={0} borderColor="transparent" />
          </Group>
        )} />
      </Group>
    </Scene>;
  },
});
